In js/spine-edit.js, add a helper next to mainIdx or insertIndexAt. It returns the anchor for cut j: the nearest real clip before j, or failing that the first clip from j on. A card is always followed by a clip, so that second case covers a leading card.

```js
function rowAnchor(R, j, skip) {
  for (let k = j - 1; k >= 0; k--) if (!R.main[k].slot && R.main[k].id !== skip) return R.main[k].id;
  for (let k = j; k < R.main.length; k++) if (!R.main[k].slot && R.main[k].id !== skip) return R.main[k].id;
  return null;
}
